// Form Trigger fields
const formNiche = isFormTrigger ? (item['Website Niche'] || '') : '';
const formType  = isFormTrigger ? (item['Website Type']  || '') : '';
const formStyle = isFormTrigger ? (item['Design Style']  || '') : '';

// Webhook / Manual fields
const webhookNiche = body.searchNiche || body.niche || body.query || '';

// Default used for Manual + Schedule triggers
const DEFAULT_NICHE = 'premium pokemon card ecommerce store';

const searchNiche = formNiche  || webhookNiche || DEFAULT_NICHE;
const websiteType = formType   || body.type    || 'E-Commerce Store';
const designStyle = formStyle  || body.style   || 'Modern Dark';
const searchQuery = 'best ' + searchNiche + ' website design top rated ecommerce';

const nicheSlug = searchNiche
  .replace(/[^a-z0-9]/gi, '-')
  .toLowerCase()
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 35);

console.log('[Parse] isForm=' + isFormTrigger + ' niche="' + searchNiche + '"');

return [{ json: {
  searchNiche,
  websiteType,
  designStyle,
  searchQuery,
  nicheSlug,
  isFormTrigger,
  FIRECRAWL_KEY: 'fc-471db502e79143e0982f3d2638b8ccdb',
  CLAUDE_KEY: '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',
  CLAUDE_MODEL: 'claude-sonnet-4-6',
  VERCEL_TOKEN: 'vcp_81CNUWp76sVnicfxBK2vhYY5ynoMbYx6ZOhh7iRVdI3tp3jPzl3hjPJM',
  startedAt: new Date().toISOString()
}}];

let searchResp = $input.item.json;
const cfg = $('Parse Input').item.json;

// Decode Buffer/stream if Firecrawl response came back as a Node.js Readable stream
if (!searchResp?.data && searchResp?._readableState) {
  try {
    const chunks = Array.isArray(searchResp._readableState.buffer) ? searchResp._readableState.buffer : [];
    const allBytes = [];
    for (const chunk of chunks) {
      const d = chunk?.data;
      if (Array.isArray(d)) allBytes.push(...d);
      else if (d?.type === 'Buffer' && Array.isArray(d.data)) allBytes.push(...d.data);
    }
    if (allBytes.length > 0) {
      searchResp = JSON.parse(Buffer.from(allBytes).toString('utf-8'));
      console.log('[n3] Decoded Firecrawl stream buffer: ' + allBytes.length + ' bytes');
    }
  } catch(bufErr) {
    console.log('[n3] Buffer decode error: ' + bufErr.message);
  }
}

const results = Array.isArray(searchResp?.data) ? searchResp.data : [];

const sites = results.slice(0, 5).map((r, i) => ({
  n: i + 1,
  url: r.url || '',
  title: r.title || r.metadata?.title || 'Site ' + (i + 1),
  desc: r.description || r.metadata?.description || '',
  content: (r.markdown || '').substring(0, 1500)
}));

const sitesText = sites.length
  ? sites.map(s =>
      '## Site ' + s.n + ': ' + s.title + '\nURL: ' + s.url + '\n' + s.desc + '\n\n' + s.content + '\n---'
    ).join('\n\n')
  : '(No live scrape data — use your expertise for best-practice ' + cfg.searchNiche + ' design patterns.)';

const promptText =
  'You are a senior UI/UX strategist. Analyse these top ' + cfg.searchNiche + ' websites.\n\n' +
  sitesText.substring(0, 7500) +
  '\n\nReturn ONLY valid JSON with no markdown fences:\n' +
  '{\n' +
  '  "brandName": "creative name for a ' + cfg.searchNiche + ' store",\n' +
  '  "tagline": "short brand tagline",\n' +
  '  "colorPalette": { "primary": "#hex", "secondary": "#hex", "accent": "#hex", "background": "#hex", "cardBg": "#hex", "textPrimary": "#hex", "textSecondary": "#hex" },\n' +
  '  "navigation": { "items": ["Home","Shop","...up to 6"], "hasSearch": true, "hasCart": true },\n' +
  '  "heroSection": { "headline": "compelling 5-7 word headline", "subheadline": "1 supporting sentence", "primaryCTA": "Shop Now", "secondaryCTA": "View Sale" },\n' +
  '  "trustElements": ["4 short trust badges"],\n' +
  '  "productCategories": ["6 category names"],\n' +
  '  "sampleProducts": [{ "name": "...", "price": "$XX.XX", "originalPrice": "$XX.XX", "badge": "New|Sale|Hot|Rare", "rating": 4.8, "reviews": 245 }],\n' +
  '  "footerLinks": { "company": ["About","Blog","Press"], "support": ["FAQ","Contact","Returns"], "social": ["Instagram","Twitter","YouTube"] }\n' +
  '}';

const analyzeRequest = JSON.stringify({
  model: cfg.CLAUDE_MODEL,
  max_tokens: 1800,
  messages: [{ role: 'user', content: promptText }]
});

console.log('[Analysis] ' + sites.length + ' sites found for "' + cfg.searchNiche + '"');

return [{ json: {
  searchNiche: cfg.searchNiche,
  websiteType: cfg.websiteType,
  designStyle: cfg.designStyle,
  nicheSlug: cfg.nicheSlug,
  isFormTrigger: cfg.isFormTrigger,
  sitesFound: sites.length,
  urls: sites.map(s => s.url).filter(Boolean),
  FIRECRAWL_KEY: cfg.FIRECRAWL_KEY,
  CLAUDE_KEY: cfg.CLAUDE_KEY,
  CLAUDE_MODEL: cfg.CLAUDE_MODEL,
  VERCEL_TOKEN: cfg.VERCEL_TOKEN,
  analyzeRequest
}}];

let resp = $input.item.json;
const prev = $('Build Analysis Prompt').item.json;

// Claude sometimes returns a Node.js Readable stream Buffer instead of parsed JSON.
// Decode it by reading the raw bytes from _readableState.buffer.
if (!resp?.content && resp?._readableState) {
  try {
    const chunks = Array.isArray(resp._readableState.buffer) ? resp._readableState.buffer : [];
    const allBytes = [];
    for (const chunk of chunks) {
      const d = chunk?.data;
      if (Array.isArray(d)) allBytes.push(...d);
      else if (d?.type === 'Buffer' && Array.isArray(d.data)) allBytes.push(...d.data);
    }
    if (allBytes.length > 0) {
      resp = JSON.parse(Buffer.from(allBytes).toString('utf-8'));
      console.log('[n5] Decoded stream buffer: ' + allBytes.length + ' bytes → model: ' + (resp.model || '?'));
    }
  } catch(bufErr) {
    console.log('[n5] Buffer decode error: ' + bufErr.message);
  }
}

const raw = resp?.content?.[0]?.text || '';
let d = {};
try {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) d = JSON.parse(m[0]);
} catch (e) {}

const n = prev.searchNiche;

// Fill defaults so generation never lacks context
d.brandName    = d.brandName    || n.split(' ').map(w => w[0].toUpperCase() + w.slice(1)).join('') + 'Store';
d.tagline      = d.tagline      || 'Premium ' + n + ' — Authentic & Affordable';
d.colorPalette = d.colorPalette || { primary: '#0f172a', secondary: '#1e293b', accent: '#f59e0b', background: '#f8fafc', cardBg: '#ffffff', textPrimary: '#0f172a', textSecondary: '#64748b' };
d.navigation   = d.navigation   || { items: ['Home','Shop','New Arrivals','Sale','About','Contact'], hasSearch: true, hasCart: true };
d.heroSection  = d.heroSection  || { headline: 'Shop Premium ' + n, subheadline: 'Discover the finest selection at unbeatable prices', primaryCTA: 'Shop Now', secondaryCTA: 'View Collection' };
d.trustElements    = d.trustElements    || ['Free Shipping $50+','100% Authentic','30-Day Returns','SSL Secure'];
d.productCategories = d.productCategories || ['New Arrivals','Best Sellers','Rare Finds','Bundles','Sale','Collections'];

const fallbackProducts = [
  { name: n + ' Booster Box',    price: '$129.99', originalPrice: '$149.99', badge: 'Sale', rating: 4.9, reviews: 412 },
  { name: 'Rare Holo Collection', price: '$89.99',  originalPrice: '$89.99',  badge: 'Hot',  rating: 4.8, reviews: 287 },
  { name: 'Starter Bundle',       price: '$29.99',  originalPrice: '$39.99',  badge: 'Sale', rating: 4.7, reviews: 523 },
  { name: 'Elite Trainer Box',    price: '$54.99',  originalPrice: '$54.99',  badge: 'New',  rating: 4.8, reviews: 189 },
  { name: 'Premium Grade PSA',    price: '$199.99', originalPrice: '$219.99', badge: 'Rare', rating: 5.0, reviews: 94  },
  { name: 'Mega Collection',      price: '$179.99', originalPrice: '$199.99', badge: 'Hot',  rating: 4.9, reviews: 156 },
  { name: 'Vintage Pack',         price: '$44.99',  originalPrice: '$44.99',  badge: 'New',  rating: 4.6, reviews: 321 },
  { name: 'Championship Set',     price: '$74.99',  originalPrice: '$89.99',  badge: 'Sale', rating: 4.8, reviews: 208 }
];

const sp = (d.sampleProducts || []).slice(0, 8);
while (sp.length < 8) sp.push(fallbackProducts[sp.length]);
d.sampleProducts = sp;
d.footerLinks = d.footerLinks || { company: ['About Us','Blog','Press'], support: ['FAQ','Contact','Returns'], social: ['Instagram','Twitter','YouTube'] };

const p = d.colorPalette;
const styleOverride = prev.designStyle || 'Modern Dark';

const htmlPrompt =
  'Build a complete, stunning e-commerce landing page HTML file. Output ONLY raw HTML starting with <!DOCTYPE html> — NO explanations, NO markdown, NO code fences.\n\n' +
  '=== STORE INFO ===\n' +
  'Name: ' + d.brandName + ' | Niche: ' + n + ' | Tagline: ' + d.tagline + '\n' +
  'Hero: "' + d.heroSection.headline + '" / "' + d.heroSection.subheadline + '"\n' +
  'CTAs: [' + d.heroSection.primaryCTA + '] [' + d.heroSection.secondaryCTA + ']\n' +
  'Nav links: ' + d.navigation.items.join(' | ') + '\n' +
  'Trust: ' + d.trustElements.join(' | ') + '\n\n' +
  '=== REQUIRED TAILWIND CLASSES (copy exactly) ===\n' +
  'body: class="bg-slate-900 text-slate-100"\n' +
  'navbar: class="fixed top-0 w-full z-50 bg-slate-900/95 backdrop-blur-md border-b border-slate-700/50 px-6 py-4"\n' +
  'hero: class="pt-24 min-h-screen bg-gradient-to-b from-slate-900 to-slate-800 flex flex-col items-center justify-center text-center px-4"\n' +
  'hero h1: class="text-5xl md:text-7xl font-black text-white mb-6 leading-tight"\n' +
  'hero p: class="text-xl text-slate-300 max-w-2xl mb-10"\n' +
  'primary btn: class="bg-amber-500 hover:bg-amber-400 text-slate-900 font-black px-10 py-4 rounded-2xl text-lg transition-all"\n' +
  'secondary btn: class="border-2 border-amber-500 text-amber-400 hover:bg-amber-500/10 font-bold px-10 py-4 rounded-2xl text-lg transition-all"\n' +
  'products section: class="py-24 bg-slate-800"\n' +
  'section h2: class="text-4xl font-black text-white text-center mb-16"\n' +
  'product card: class="bg-slate-900 rounded-2xl overflow-hidden border border-slate-700/50 hover:border-amber-500/50 transition-all duration-300 group"\n' +
  'product name: class="text-white font-bold text-sm mb-2"\n' +
  'product price: class="text-amber-400 font-black text-xl"\n' +
  'add to cart btn: class="bg-amber-500 hover:bg-amber-400 text-slate-900 text-sm font-black px-4 py-2 rounded-xl transition"\n' +
  'category card: class="relative rounded-2xl overflow-hidden h-56 cursor-pointer group"\n' +
  'category overlay: class="absolute inset-0 bg-gradient-to-t from-slate-900 via-slate-900/20 to-transparent"\n' +
  'category label: class="absolute bottom-6 left-6 text-white text-xl font-black"\n' +
  'footer: class="bg-slate-950 border-t border-slate-800 py-16 px-6"\n' +
  'footer text: class="text-slate-400"\n' +
  'footer heading: class="text-white font-bold mb-4"\n' +
  'footer link: class="text-slate-400 hover:text-amber-400 text-sm transition"\n\n' +
  '=== PRODUCTS (use picsum.photos seeds 10-17 for images) ===\n' +
  JSON.stringify(d.sampleProducts) + '\n\n' +
  '=== CATEGORIES (use picsum.photos seeds 30-35) ===\n' +
  d.productCategories.join(', ') + '\n\n' +
  '=== FOOTER LINKS ===\n' +
  'Company: ' + (d.footerLinks.company||[]).join(', ') + ' | Support: ' + (d.footerLinks.support||[]).join(', ') + ' | Social: ' + (d.footerLinks.social||[]).join(', ') + '\n\n' +
  '=== JAVASCRIPT (before </body>) ===\n' +
  'let c=0; function addToCart(){ c++; const el=document.getElementById("cc"); if(el) el.textContent=c; }\n' +
  'Smooth scroll for #products and #categories anchor links.\n\n' +
  '=== BUILD ORDER ===\n' +
  '1. <head>: charset, viewport, title="' + d.brandName + '", TailwindCSS CDN script\n' +
  '2. NAVBAR: logo text-amber-400 font-black left | nav links center (hidden on mobile) | cart button right with id="cc" counter\n' +
  '3. HERO: pill badge → giant h1 text-white → p text-slate-300 → 2 CTA buttons → 4 trust badges in bg-slate-800/60 border border-slate-700 rounded-xl p-4 grid grid-cols-2 md:grid-cols-4 mt-12\n' +
  '4. PRODUCTS section id="products": h2 + 4-col card grid (2-col mobile), 8 cards with img/badge/name/stars/price/button\n' +
  '5. CATEGORIES section id="categories" bg-slate-900: h2 + 3-col grid (2-col mobile), 6 cards with picsum bg-cover + gradient overlay + text\n' +
  '6. FOOTER bg-slate-950: 3-col grid (brand+tagline | company links | support links) + bottom bar with copyright\n' +
  '7. <script> with addToCart() and smooth scroll\n\n' +
  'FINAL CHECK before outputting: every section has visible text (white/amber on dark). Product cards have images. All 6 sections present. Starts with <!DOCTYPE html>.';

const htmlRequest = JSON.stringify({
  model: prev.CLAUDE_MODEL,
  max_tokens: 6000,
  messages: [{ role: 'user', content: htmlPrompt }]
});

return [{ json: {
  searchNiche: prev.searchNiche,
  websiteType: prev.websiteType,
  designStyle: prev.designStyle,
  nicheSlug: prev.nicheSlug,
  isFormTrigger: prev.isFormTrigger,
  sitesFound: prev.sitesFound,
  urls: prev.urls,
  design: d,
  CLAUDE_KEY: prev.CLAUDE_KEY,
  CLAUDE_MODEL: prev.CLAUDE_MODEL,
  VERCEL_TOKEN: prev.VERCEL_TOKEN,
  htmlRequest
}}];

let resp = $input.item.json;
const prev = $('Build HTML Prompt').item.json;

// Decode Buffer/stream if Claude returned a Node.js Readable stream instead of parsed JSON
if (!resp?.content && resp?._readableState) {
  try {
    const chunks = Array.isArray(resp._readableState.buffer) ? resp._readableState.buffer : [];
    const allBytes = [];
    for (const chunk of chunks) {
      const d = chunk?.data;
      if (Array.isArray(d)) allBytes.push(...d);
      else if (d?.type === 'Buffer' && Array.isArray(d.data)) allBytes.push(...d.data);
    }
    if (allBytes.length > 0) {
      resp = JSON.parse(Buffer.from(allBytes).toString('utf-8'));
      console.log('[n7] Decoded stream buffer: ' + allBytes.length + ' bytes → model: ' + (resp.model || '?'));
    }
  } catch(bufErr) {
    console.log('[n7] Buffer decode error: ' + bufErr.message);
  }
}

// Detect empty response (n8n HTTP error with onError:continueRegularOutput passes {} )
const isEmptyResp = !resp || Object.keys(resp).length === 0;
const noContent   = !resp?.content || !Array.isArray(resp.content) || resp.content.length === 0;

let claudeError = null;
if (resp?.error && resp.error.type)   { claudeError = resp.error.type + ': ' + (resp.error.message || JSON.stringify(resp.error)); }
else if (resp?.type === 'error')       { claudeError = 'api_error: ' + JSON.stringify(resp.error || resp); }
else if (isEmptyResp)                  { claudeError = 'HTTP_FAIL: Claude node returned empty object — check n8n execution logs for network/timeout error'; }
else if (noContent)                    { claudeError = 'NO_CONTENT: ' + JSON.stringify(resp).substring(0, 300); }

const raw = resp?.content?.[0]?.text || '';
console.log('[Claude HTML] raw=' + raw.length + ' chars | stop=' + resp?.stop_reason + ' | error=' + claudeError);
console.log('[Claude HTML] respKeys=' + Object.keys(resp || {}).join(',') + ' | preview: ' + raw.substring(0, 200));
if (claudeError) console.log('[Claude HTML] API ERROR: ' + claudeError);

let html = raw.trim();

const fenced       = raw.match(/```html?\s*([\s\S]*?)```/i);
const doctype      = raw.match(/(<!DOCTYPE[\s\S]*<\/html>)/i);
const doctypeStart = raw.toLowerCase().indexOf('<!doctype');
if (fenced)              html = fenced[1].trim();
else if (doctype)        html = doctype[1].trim();
else if (doctypeStart >= 0) html = raw.substring(doctypeStart).trim();

if (!html.toLowerCase().startsWith('<!doctype')) {
  const brand = prev.design?.brandName || prev.searchNiche || 'AI Website';
  html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<title>' + brand + '</title>'
    + '<script src="https://cdn.tailwindcss.com"></script></head>'
    + '<body class="bg-gray-900 text-white flex items-center justify-center min-h-screen p-8">'
    + '<div class="max-w-lg text-center">'
    + '<h1 class="text-4xl font-black text-amber-400 mb-4">' + brand + '</h1>'
    + '<p class="text-gray-400 mb-6">HTML generation returned incomplete output. Raw preview:</p>'
    + '<pre class="bg-gray-800 p-4 rounded text-left text-xs text-gray-300 overflow-auto">'
    + raw.substring(0, 600).replace(/</g, '&lt;') + '</pre>'
    + '</div></body></html>';
}

console.log('[HTML] ' + html.length + ' chars | brand: ' + (prev.design?.brandName || prev.searchNiche));

return [{ json: {
  html,
  htmlLength: html.length,
  claudeError,
  rawLength: raw.length,
  searchNiche: prev.searchNiche,
  websiteType: prev.websiteType,
  designStyle: prev.designStyle,
  nicheSlug: prev.nicheSlug,
  isFormTrigger: prev.isFormTrigger,
  brandName: prev.design?.brandName || prev.searchNiche,
  tagline: prev.design?.tagline || '',
  sitesFound: prev.sitesFound,
  urls: prev.urls || [],
  VERCEL_TOKEN: prev.VERCEL_TOKEN,
  generatedAt: new Date().toISOString()
}}];

const prev = $input.item.json;
const VERCEL_TOKEN = prev.VERCEL_TOKEN || '';
const hasToken = !!(VERCEL_TOKEN && VERCEL_TOKEN.trim() && !VERCEL_TOKEN.includes('{{'));

// Save generated HTML to static data so the preview webhook can serve it as backup
try {
  const sd = $getWorkflowStaticData('global');
  sd.lastHtml    = prev.html        || '';
  sd.lastBrand   = prev.brandName   || '';
  sd.lastNiche   = prev.searchNiche || '';
  sd.lastUpdated = new Date().toISOString();
  console.log('[Backup] stored ' + (prev.html||'').length + ' chars for: ' + (prev.brandName||''));
} catch(e) { console.log('[Backup] static data error: ' + e.message); }

const projectName = 'ai-' + (prev.nicheSlug || 'website').substring(0, 28) + '-' + Date.now().toString().slice(-5);

const deployRequest = JSON.stringify({
  name: projectName,
  files: [{ file: 'index.html', data: prev.html, encoding: 'utf-8' }],
  target: 'production'
});

console.log('[Vercel] hasToken=' + hasToken + ' project=' + projectName);

return [{ json: { ...prev, VERCEL_TOKEN, hasToken, deployRequest, projectName } }];

const input = $input.item.json;

// Detect if we came from the Vercel HTTP call or the skip branch
const skipped = !!(input.skippedDeploy);

// When skipped, look back at Build Vercel Deploy for html/meta
const prev = skipped ? $('Build Vercel Deploy').item.json : $('Build Vercel Deploy').item.json;

// Decode Buffer/stream if Vercel response came back as Node.js Readable stream
let vercelData = input;
if (!skipped && !vercelData?.url && vercelData?._readableState) {
  try {
    const chunks = Array.isArray(vercelData._readableState.buffer) ? vercelData._readableState.buffer : [];
    const allBytes = [];
    for (const chunk of chunks) {
      const d = chunk?.data;
      if (Array.isArray(d)) allBytes.push(...d);
      else if (d?.type === 'Buffer' && Array.isArray(d.data)) allBytes.push(...d.data);
    }
    if (allBytes.length > 0) {
      vercelData = JSON.parse(Buffer.from(allBytes).toString('utf-8'));
      console.log('[n10] Decoded Vercel stream buffer: ' + allBytes.length + ' bytes → url: ' + (vercelData.url || 'none'));
    }
  } catch(e) {
    console.log('[n10] Vercel Buffer decode error: ' + e.message);
  }
}
const vercelResp = skipped ? {} : vercelData;
const rawUrl  = vercelResp?.url || vercelResp?.alias?.[0] || '';
const deployUrl = rawUrl ? ('https://' + rawUrl) : null;
const deployOk  = !!(deployUrl && !vercelResp?.error);

const liveUrl = deployUrl || 'NOT_DEPLOYED';

const brandName = prev.brandName   || prev.searchNiche;
const niche     = prev.searchNiche || '';
const style     = prev.designStyle || '';
const sitesRef  = (prev.urls || []).slice(0, 5).join(', ');
const isFormTrigger = prev.isFormTrigger;

const A = '#f59e0b';
const D = '#0f172a';
const C = '#1e293b';

const tokenMsg = skipped
  ? 'Add your Vercel token in Parse Input node (replace <code>{{VERCEL_TOKEN}}</code>), then re-run to get a live URL.'
  : 'There was an error deploying. Check your Vercel token is valid and try again.';

const deploySection = deployOk
  ? '<div class="url-box">\u{1F517} ' + liveUrl + '</div>'
    + '<a href="' + liveUrl + '" target="_blank" class="btn">Open Live Website \u2192</a>'
  : '<div class="url-box url-warn">' + tokenMsg + '</div>';

const responsePage = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1">'
  + '<title>Your Website is Ready \u2014 ' + brandName + '</title>'
  + '<style>*{box-sizing:border-box;margin:0;padding:0}'
  + 'body{background:' + D + ';color:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:2rem}'
  + '.card{background:' + C + ';border-radius:20px;padding:2.5rem;max-width:620px;width:100%;text-align:center;box-shadow:0 25px 60px rgba(0,0,0,.4)}'
  + '.badge{display:inline-block;background:' + (deployOk ? '#16a34a' : '#b45309') + ';color:#fff;font-size:.75rem;font-weight:700;padding:.25rem .75rem;border-radius:999px;letter-spacing:.05em;margin-bottom:1rem}'
  + 'h1{font-size:1.8rem;font-weight:800;margin-bottom:.5rem}'
  + '.sub{color:#94a3b8;font-size:.95rem;margin-bottom:1.5rem}'
  + '.url-box{background:' + D + ';border:1px solid #334155;border-radius:12px;padding:1rem 1.25rem;margin-bottom:1.25rem;word-break:break-all;font-size:.9rem;color:' + A + '}'
  + '.url-warn{color:#fbbf24;font-size:.85rem;line-height:1.6}'
  + '.btn{display:inline-block;background:' + A + ';color:#0f172a;font-weight:800;padding:.85rem 2rem;border-radius:10px;text-decoration:none;font-size:1rem;transition:opacity .2s}'
  + '.btn:hover{opacity:.85}'
  + '.meta{margin-top:1.75rem;display:grid;grid-template-columns:1fr 1fr;gap:.75rem;text-align:left}'
  + '.meta-item{background:' + D + ';border-radius:10px;padding:.75rem 1rem}'
  + '.meta-label{font-size:.7rem;color:#64748b;text-transform:uppercase;letter-spacing:.05em;margin-bottom:.2rem}'
  + '.meta-val{font-size:.85rem;font-weight:600;color:#e2e8f0}'
  + '.sources{margin-top:1.25rem;font-size:.75rem;color:#475569;line-height:1.6}'
  + '</style></head><body>'
  + '<div class="card">'
  + '<div class="badge">' + (deployOk ? '\u{1F680} Live on Vercel' : '\u2705 HTML Generated') + '</div>'
  + '<h1>\u2728 ' + brandName + '</h1>'
  + '<p class="sub">' + niche + ' \u00B7 ' + style + ' \u00B7 AI-generated from ' + (prev.sitesFound || 0) + ' real websites</p>'
  + deploySection
  + '<div class="meta">'
  + '<div class="meta-item"><div class="meta-label">Website Type</div><div class="meta-val">' + (prev.websiteType || 'E-Commerce') + '</div></div>'
  + '<div class="meta-item"><div class="meta-label">HTML Size</div><div class="meta-val">' + (((prev.htmlLength || 0) / 1024).toFixed(1)) + ' KB</div></div>'
  + '<div class="meta-item"><div class="meta-label">Sites Analyzed</div><div class="meta-val">' + (prev.sitesFound || 0) + ' websites</div></div>'
  + '<div class="meta-item"><div class="meta-label">Generated At</div><div class="meta-val">' + new Date().toLocaleTimeString() + '</div></div>'
  + '</div>'
  + (sitesRef ? '<p class="sources">\u{1F4CC} Sources: ' + sitesRef + '</p>' : '')
  + '<p style="margin-top:1.25rem;font-size:.75rem;color:#334155">Re-run the form to generate a new niche anytime</p>'
  + '</div></body></html>';

const vercelError = skipped ? null
  : vercelResp?.error                                            ? JSON.stringify(vercelResp.error)
  : (vercelResp?.name === 'AxiosError' || vercelResp?.code)      ? (vercelResp.message || vercelResp.code)
  : (!deployOk && !vercelResp?._readableState)                   ? 'NO_URL: ' + JSON.stringify(Object.keys(vercelResp || {}))
  : null;

return [{ json: {
  deployUrl,
  deployOk,
  skipped,
  liveUrl,
  responsePage,
  brandName,
  niche,
  style,
  htmlLength: prev.htmlLength,
  sitesFound: prev.sitesFound,
  claudeError: prev.claudeError || null,
  rawLength: prev.rawLength || 0,
  vercelError,
  isFormTrigger,
  generatedAt: prev.generatedAt
}}];

const sd = $getWorkflowStaticData('global');
const html = sd.lastHtml || '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>Preview</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-900 text-white flex items-center justify-center min-h-screen"><div class="text-center p-8"><h1 class="text-3xl font-bold text-amber-400 mb-6">No Website Generated Yet</h1><p class="text-gray-400 mb-2">Run the workflow first, then refresh this page.</p><p class="text-gray-500 text-sm">Trigger the Manual Trigger or fill the form.</p></div></body></html>';
return [{ json: { html, brand: sd.lastBrand || '', niche: sd.lastNiche || '', updatedAt: sd.lastUpdated || 'never' } }];
